/**
 * @method
 * @name dataValidation
 * @description data Validation 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dataValidation = async function () {
    if ($c.str.getByteLength($c.util.getComponent('ipt_isurCd').getValue()) === 0) {
        await $c.win.alert("발행기관을 먼저 조회하세요.");
        ($c.util.getComponent('ipt_isurCd') && $c.util.getComponent('ipt_isurCd').setFocus ? $c.util.getComponent('ipt_isurCd').setFocus() : $c.util.getComponent('ipt_isurCd').focus());
        return true;
    }
    const nullInput = $("#conTable input:visible[name!=''][type='text'][value='']");
    for (let i = 0; i < nullInput.length; i++) {
        if ($c.str.getByteLength($($(nullInput)[i]).val()) === 0) {
            const ipNm = $($(nullInput)[i]).attr("name");
            if (($($(nullInput)[i]).attr("id") === "nusual_isu_cond_contn") || ($($(nullInput)[i]).attr("id") === "uly_isu_nm1") || ($($(nullInput)[i]).attr("id") === "uly_compst_rto1") || ($($(nullInput)[i]).attr("id") === "misc_idx_contn") || ($($(nullInput)[i]).attr("id") === "misc_fnc_uly_contn") || ($($(nullInput)[i]).attr("id") === "isu_shrs")) {
                continue;
            }
            const labelNm = $('[for="' + ipNm + '"]').text();
            await $c.win.alert(labelNm + "(을)를 입력하세요.");
            /* TODO Stage2: [sdd] 미실현 동작: set_focus (대상 미해석) — 전환 미완 */ /* unresolved-target intent:set_focus — {target}.focus({args}) */
            return true;
        }
    }
    const isu_rnd = $c.util.getComponent('ipt_isuRnd').getValue();
    const fnc_uly_tp_cd = $c.util.getComponent('slc_fncUlyTpCd').getValue();
    if ($c.str.getByteLength($c.util.getComponent('ipt_isuNm').getValue()) > 80) {
        await $c.win.alert("한글종목명을 40자이내로 입력해 주세요");
        $c.util.getComponent("ipt_isuNm").focus();
        return true;
    }
    if ($c.str.getByteLength($c.util.getComponent('ipt_isuEngNm').getValue()) === 0) {
        await $c.win.alert("영문종목명을 입력해 주세요");
        $c.util.getComponent("ipt_isuEngNm").focus();
        return true;
    }
    if (parseInt(isu_rnd, 10) <= 0) {
        await $c.win.alert("발행회차에 입력한 값은 0 보다 커야합니다.");
        ($c.util.getComponent('ipt_isuRnd') && $c.util.getComponent('ipt_isuRnd').setFocus ? $c.util.getComponent('ipt_isuRnd').setFocus() : $c.util.getComponent('ipt_isuRnd').focus());
        return true;
    } else {
        if (parseInt(isu_rnd, 10) > 15467) {
            await $c.win.alert("발행회차에 입력한 값은 15467 보다 작아야 합니다.");
            ($c.util.getComponent('ipt_isuRnd') && $c.util.getComponent('ipt_isuRnd').setFocus ? $c.util.getComponent('ipt_isuRnd').setFocus() : $c.util.getComponent('ipt_isuRnd').focus());
            return true;
        }
    }
    if ($c.util.getComponent('cal_expDd').getValue() <= $c.util.getComponent('cal_isuDd').getValue()) {
        await $c.win.alert("만기일을 발행일 이후로 입력하세요");
        ($c.util.getComponent('cal_expDd') && $c.util.getComponent('cal_expDd').setFocus ? $c.util.getComponent('cal_expDd').setFocus() : $c.util.getComponent('cal_expDd').focus());
        return true;
    }
    if ($c.str.getByteLength(fnc_uly_tp_cd) === 0) {
        await $c.win.alert("기초자산종류를 입력하세요");
        ($c.util.getComponent('slc_fncUlyTpCd') && $c.util.getComponent('slc_fncUlyTpCd').setFocus ? $c.util.getComponent('slc_fncUlyTpCd').setFocus() : $c.util.getComponent('slc_fncUlyTpCd').focus());
        return true;
    }
    if (fnc_uly_tp_cd === '1') {
        if ($c.str.getByteLength($c.util.getComponent('ipt_ulyIsuNm1').getValue()) === 0) {
            await $c.win.alert("기초자산이 '주식'일 경우 해당 '주권발행기관'을 입력하세요.");
            $c.util.getComponent("ipt_ulyIsuNm1").focus();
            return true;
        }
        if ($c.str.getByteLength($c.util.getComponent('ipt_ulyCompstRto1').getValue()) === 0) {
            await $c.win.alert("구성주식비율을 입력하세요.");
            $c.util.getComponent("ipt_ulyCompstRto1").focus();
            return true;
        }
        if ($c.util.getComponent('ipt_ulyCompstRto1').getValue() > 1) {
