            $c.util.getComponent("ipt_ulyCompstRto1").focus();
            return true;
        }
    } else {
        if (fnc_uly_tp_cd === '3') {
            if ($c.str.getByteLength($c.util.getComponent('slc_elwObjIdxTpCd').getValue()) === 0) {
                await $c.win.alert("기초자산이 '주가지수'일 경우 해당 '지수'를 선택하세요.");
                $c.util.getComponent("slc_elwObjIdxTpCd").focus();
                return true;
            }
        }
    }
    if ($c.util.getComponent('slc_elwObjIdxTpCd').getValue() === '9' && $c.str.getByteLength($c.util.getComponent('ipt_miscIdxContn').getValue()) === 0) {
        await $c.win.alert("주가지수가 기타이면 기타내용을 입력하세요.");
        $c.util.getComponent("ipt_miscIdxContn").focus();
        return true;
    }
    const std_cd_yn = $('input[name=std_cd_yn]:checked').val();
    if ($('input[name=elw_rght_tp_kind_cd]:checked').val() === '3') {
        if (std_cd_yn !== "N") {
            await $c.win.alert("조기종료형은 비표준 워런트로만 신청 가능합니다");
            /* TODO Stage2: [sdd] 미실현 동작: set_focus (대상 미해석) — 전환 미완 */ /* unresolved-target intent:set_focus — {target}.focus({args}) */
            return true;
        }
    }
    if ($c.str.getByteLength($c.util.getComponent('ipt_nusualIsuCondContn').getValue()) > 0) {
        if ($c.util.getComponent('ipt_nusualIsuCondContn').getValue().indexOf("\t") > -1 || $c.util.getComponent('ipt_nusualIsuCondContn').getValue().indexOf("\n") > -1 || $c.util.getComponent('ipt_nusualIsuCondContn').getValue().indexOf("\r") > -1) {
