            $("#ipt_nusualIsuCondContn").select();
            return true;
        }
    }
    const exer_tp_cd = $('input[name=exer_tp_cd]:checked').val();
    const exp_dd = $c.util.getComponent('cal_expDd').getValue();
    if (!$('input[name=group]').is(":checked")) {
