    $c.util.getComponent('ipt_cfiCdGroup').setValue($('input[name=group]:checked').val());
    $c.util.getComponent('ipt_cfiCdAttr1').setValue(($c.util.getComponent("slc_attr01").getValue() || ''));
    $c.util.getComponent('ipt_cfiCdAttr2').setValue(($c.util.getComponent("slc_attr02").getValue() || ''));
    $c.util.getComponent('ipt_cfiCdAttr3').setValue(($c.util.getComponent("slc_attr03").getValue() || ''));
    $c.util.getComponent('ipt_cfiCdAttr4').setValue(($c.util.getComponent("slc_attr04").getValue() || ''));
    $c.util.getComponent('ipt_fisnVal').setValue("");
    $c.util.getComponent('ipt_fisnMakeYn').setValue("N");
};

/**
 * @method
 * @name makeFisn
 * @description make Fisn 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.makeFisn = async function () {
    $c.util.getComponent("ipt_comEngAbbrv").setValue(fn_cut_spacingWords($c.util.getComponent('ipt_comEngAbbrv').getValue(), 15));  // TODO Stage2(pcc 반입 2차): as-is 공통 fn_cut_spacingWords — as-is 공통(폼 전역 의존) — 반입 보류
    const thisForm = $('#JLDINF11000');
    const chkBl = await scwin.dataValidation();
    if (chkBl) {
        return;
    }
    let temp = "";
    temp += $c.util.getComponent('ipt_comEngAbbrv').getValue();
    if ($c.util.getComponent('slc_attr03').getValue() === "B") {
        temp += "/C P";
    } else {
        temp += "/" + $c.util.getComponent('slc_attr03').getValue();
    }
    if ($c.util.getComponent('slc_attr02').getValue() === "T") {
        temp += " Trd Wt";
    } else {
        if ($c.util.getComponent('slc_attr02').getValue() === "N") {
            temp += " Nkd Wt";
        } else {
            if ($c.util.getComponent('slc_attr02').getValue() === "C") {
                temp += " Cov Wt";
            }
        }
    }
    if ($c.util.getComponent('slc_attr01').getValue() === "B") {
        temp += " Bskt";
    } else {
        if ($c.util.getComponent('slc_attr01').getValue() === "S") {
            temp += " EQ";
        } else {
            if ($c.util.getComponent('slc_attr01').getValue() === "D") {
                temp += " Bd";
            } else {
                if ($c.util.getComponent('slc_attr01').getValue() === "T") {
                    temp += " Comd";
                } else {
                    if ($c.util.getComponent('slc_attr01').getValue() === "C") {
                        temp += " Cy";
                    } else {
                        if ($c.util.getComponent('slc_attr01').getValue() === "I") {
                            temp += " Idx";
                        } else {
                            if ($c.util.getComponent('slc_attr01').getValue() === "N") {
                                temp += " IR";
                            } else {
                                if ($c.util.getComponent('slc_attr01').getValue() === "M") {
                                    temp += " Oth";
                                }
                            }
                        }
                    }
                }
            }
        }
    }
    temp += " " + $c.str.replaceAll($c.util.getComponent('cal_expDd').getValue(), "-", "");
    $c.util.getComponent('ipt_fisnVal').setValue(fn_cut_spacingWords(temp, 35));  // TODO Stage2(pcc 반입 2차): as-is 공통 fn_cut_spacingWords — as-is 공통(폼 전역 의존) — 반입 보류
    $c.util.getComponent('ipt_fisnVal').setValue(($c.util.getComponent("ipt_fisnVal").getValue() || '').toUpperCase());
    $c.util.getComponent('ipt_fisnMakeYn').setValue("Y");
};

/**
 * @method
 * @name chk_chrg_nm
 * @description chk chrg nm 처리
 * @param {*} fm fm
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.chk_chrg_nm = async function (fm) {
    const len = $c.str.getByteLength(fm.chrg_nm.value);
    if (len > 20) {
        await $c.win.alert("이름은 한글10자, 영문20자 이내로 입력하세요.");
        chrg_nm.focus();
        return;
    }
};
